-- Sample admin posts for testing
INSERT INTO admin_posts (title, content, category, badge_text, position, created_at) VALUES
('კახეთის რეგიონის განვითარების გეგმა', 'საქართველოს მთავრობა აცხადებს კახეთის რეგიონის სოფლის მეურნეობის განვითარების ახალ პროგრამას. პროგრამა მოიცავს მევენახეებისთვის სახელმწიფო დახმარებას, ახალი საწარმოების დაფინანსებას და ტურიზმის განვითარებას.', 'სახელმწიფო პროგრამები', 'ოფიციალური განცხადება', 'left_top', NOW() - INTERVAL '2 days'),

('საგზაო სამუშაოები თელავში', 'დაწყებულია საგზაო სამუშაოები თელავის მუნიციპალიტეტში. სამუშაოები მოიცავს ქალაქის ცენტრალური ქუჩების რეაბილიტაციას და საფეხმავლო ბილიკების მოწყობას. სამუშაოები დასრულდება 2026 წლის მარტში.', 'ინფრასტრუქტურა', 'მიმდინარე სამუშაოები', 'right_top', NOW() - INTERVAL '1 day'),

('ახალი სასწავლო პროგრამა სოფლის მეურნეობაში', 'თელავის სასოფლო-სამეურნეო კოლეჯი აცხადებს ახალ სასწავლო პროგრამას "მევენახეობა და ღვინის წარმოება". პროგრამა მოიცავს თეორიულ და პრაქტიკულ სწავლებას. რეგისტრაცია მიმდინარეობს.', 'განათლება', 'სასწავლო პროგრამა', 'right_bottom', NOW() - INTERVAL '3 hours'),

('კახეთის ტურისტული რუკა განახლდა', 'გამოქვეყნდა კახეთის რეგიონის ტურისტული რუკის განახლებული ვერსია. რუკა შეიცავს ახალ ტურისტულ მარშრუტებს, სასტუმროებს და რესტორნებს. რუკა ხელმისაწვდომია ციფრულ და პაერ ფორმატში.', 'ტურიზმი', 'ახალი გამოშვება', NULL, NOW() - INTERVAL '6 hours'),

('ენერგოეფექტურობის პროგრამა', 'დაწყებულია სახლების ენერგოეფექტურობის ამაღლების პროგრამა კახეთის რეგიონში. პროგრამის ფარგლებში მოხდება სახურავების იზოლაცია, ფანჯრების ჩანაცვლება და გათბობის სისტემების მოდერნიზაცია.', 'ენერგეტიკა', 'სახელმწიფო პროგრამა', NULL, NOW() - INTERVAL '12 hours')
ON CONFLICT DO NOTHING;